// Comparar (#/comparar) — design V3Compare: one direct answer, sites A/B/C side by side, rules in sight.
// Values: LOLA + SPICE hourly series over the same window for every site (EST). Battery: N/D (not computed).
// Source of truth: this .tsx file (Preact). comparar.js is generated by `npm --prefix web run build:ts`.
import { h, Fragment, type VNode } from "../../vendor/preact/preact.module.js";
import { num, setLevel } from "../../ds/components.js";
import { buildHash, type RouteCtx } from "../../ds/router.js";
import { LayerCard, mount } from "../../ds/ui.js";
import { compareLive } from "../live-compare.js";
import { windowMetrics, type Site, type Series, type WindowMetrics } from "../data.js";
import { evaluate, rulesFromQuery, METRICS, bestIndex, type Row, type Check, type Rules } from "../compare.js";
import { scenario, ContextBar, pickedSites, seriesFor, seriesProof, HourStrip, LETTERS, setQuery, type Scenario } from "./common.js";

const G = "est";

/** Window metrics of one site plus the extra fields of the live API answer (see live-compare.ts). */
export type CmpW = WindowMetrics & { request_sha256?: string; series_sha256?: string | null; science_status?: string; provenance?: unknown };
export interface CmpRow {
  id: string; name: string; w: CmpW; site: Site; series?: Series;
  computed: boolean; checks: Check[]; fails: number; unknown: boolean; passAll: boolean;
}
export interface Comparison {
  sc: Scenario; entries: { id: string; name: string; site: Site; series?: Series; w: CmpW }[];
  rules: Rules; live: boolean; result: { rows: CmpRow[]; best: CmpRow | null; closest: CmpRow | null };
}

/** Shared loader for #/comparar and #/comparar/tecnico. */
export async function loadComparison(ctx: RouteCtx): Promise<Comparison> {
  const sc = await scenario(ctx);
  const sites = pickedSites(sc.data, ctx.query);
  const loaded = await seriesFor(sites);
  const entries = loaded.map(({ site, series, error }) => ({
    id: site.id, name: site.name, site, series,
    w: (series ? windowMetrics(series, sc.t0, sc.hours) : { status: "NOT_COMPUTED", reason: error }) as CmpW,
  }));
  const live = await compareLive(sites.map(s => s.id), sc.t0, sc.hours);
  if (live) for (const entry of entries) entry.w = live.get(entry.id) as CmpW;
  const rules = rulesFromQuery(ctx.query);
  return { sc, entries, rules, live: Boolean(live), result: evaluate(entries, rules) as unknown as Comparison["result"] };
}

export const fmtMetric = (v: unknown, unit: string) => (unit === "%" ? num(v, 0, "%") : num(v, 0, " h"));
const short = (n: string) => n.replace(/\s*\(.*\)$/, "");

export function SitePickers({ ctx, sc, entries }: { ctx: RouteCtx; sc: Scenario; entries: { id: string }[] }): VNode {
  return (
    <div class="row wrap" role="group" aria-label="Locais comparados">{LETTERS.slice(0, entries.length).map((L, i) =>
      <label class="ctx glass"><span class="wpill-letter">{L}</span>
        <select aria-label={"Local " + L} onChange={e => setQuery(ctx, { [L.toLowerCase()]: (e.target as HTMLSelectElement).value })}>
          {sc.data.sites.map(s => <option value={s.id} {...(s.id === entries[i].id ? { defaultSelected: true } : {})}>{short(s.name)}</option>)}
        </select></label>)}</div>
  );
}

export async function render(outlet: HTMLElement, ctx: RouteCtx): Promise<void> {
  const { sc, entries, rules, result, live } = await loadComparison(ctx);
  const { rows, best, closest } = result;
  const letterOf = (id: string) => LETTERS[rows.findIndex(r => r.id === id)];

  const answerText = best
    ? <><span class="big">{letterOf(best.id) + " · " + short(best.name)}</span>atende às três regras e tem mais horas com Sol e Terra juntos.</>
    : closest
      ? <><span class="big">Nenhum atende a tudo</span>{"O mais próximo é " + letterOf(closest.id) + " · " + short(closest.name) + " (" + closest.fails + " regra(s) falham)."}</>
      : <><span class="big">N/D</span>Não há série calculada para esta janela.</>;

  const metricCards = METRICS.map(m => {
    const bi = bestIndex(rows as unknown as Row[], m);
    return <LayerCard title={m.label} badge="est" globalBadge={G}
      answer={<>
        <div class="vals" style={{ "--n": String(rows.length) } as never}>{rows.map((r, i) => {
          const v = r.computed ? (r.w as never as Record<string, number>)[m.key] : NaN;
          const chk = r.checks.find(c => c.key === m.key);
          const fail = chk && chk.pass === false;
          return <div class={"v" + (i === bi ? " best" : "") + (fail ? " fail" : "")}>
            <span>{LETTERS[i] + (i === bi ? " · melhor" : "") + (fail ? " · falha" : "")}</span><b>{fmtMetric(v, m.unit)}</b></div>;
        })}</div>
        {m.rule ? <span class="rule">{"Regra: " + m.text!(rules) + " (premissa)"}</span> : <span class="rule">Sem regra: só informativo</span>}</>}
      why={m.key === "longestDarkH" ? "Noite longa exige bateria maior: é a sequência mais longa de horas sem Sol."
        : m.key === "longestBlackoutH" ? "Tempo seguido sem a Terra no céu: sem comunicação direta (geometria, não rádio)."
        : m.key === "sunPct" ? "Fração das horas com o centro do Sol acima do relevo." : "Fração das horas da janela, mesma definição do Explorar."}
      proof={rows.map((r, i): [string, string] => [LETTERS[i] + " · " + short(r.name), r.computed ? fmtMetric((r.w as never as Record<string, number>)[m.key], m.unit) + (m.rule ? " · margem " + fmtMetric(r.checks.find(c => c.key === m.key)!.margin, m.unit) : "") : "N/D"])} />;
  });

  mount(outlet, <>
    <div class="page-head">
      <div><p class="lbl-s">Comparar locais de pouso</p><h1 data-route-title="">Qual local atende às regras nesta janela?</h1></div>
      <ContextBar ctx={ctx} sc={sc} siteSelect={false} />
    </div>
    <p class="t3 small" role="status">{live ? "API Go ao vivo · métricas preliminares" : "API indisponível para esta janela · métricas da série estática versionada"}</p>
    <SitePickers ctx={ctx} sc={sc} entries={entries} />
    <div class="split">
      <div class="stack">
        <LayerCard title="Resposta" badge={best || closest ? "est" : "nd"} globalBadge={G} surface="glass" answer={answerText}
          why="Só geometria: Sol, Terra e noite a partir do relevo LOLA e das efemérides SPICE. As regras são premissas do protótipo, editáveis na comparação técnica. Energia e bateria não entram (N/D)."
          proof={[["Regras", "Maior noite ≤ " + rules.maxNightH + " h · Maior perda da Terra ≤ " + rules.maxEarthLossH + " h · Sol visível ≥ " + rules.minSunPct + "%"],
            ["Desempate", "mais horas com Sol e Terra juntos"], ["Origem das métricas", live ? "Go API · POST /api/compare" : "Série estática versionada"],
            ...(live ? [["SHA da requisição", entries[0]?.w.request_sha256 || "N/D"] as [string, string]] : []), ...seriesProof(entries[0] && entries[0].series, sc)]} />
        <div class="scen">{rows.map((r, i) =>
          <a class={"wpill" + (best && best.id === r.id ? " on" : "")} href={buildHash("/explorar", { site: r.id, t: ctx.query.t, d: ctx.query.d })}>
            <span class="letter">{LETTERS[i]}</span>
            <span>{short(r.name)}<small>{!r.computed ? "N/D · série indisponível" : r.passAll ? "Atende às regras" : "Falha em " + r.fails + " regra(s)"}</small></span>
            <span class="v">{r.computed ? (r.passAll ? "✓ Atende" : "✕ Falha") : "N/D"}</span>
          </a>)}</div>
        <section class="solid card"><h2 class="h-card">Sol hora a hora na janela · série estática</h2>
          <div class="stripes">{rows.map((r, i) => <div class="s"><span>{LETTERS[i]}</span>
            {r.series ? <HourStrip series={r.series} t0={sc.t0} hours={sc.hours} body="sun" /> : <span class="t3">N/D</span>}</div>)}</div>
          <p class="t3 small row"><i class="sw sw-sun" aria-hidden="true" />Sol visível<i class="sw sw-none" aria-hidden="true" />Sol abaixo do relevo</p></section>
        <div class="row wrap"><a class="btnA" href={buildHash("/comparar/tecnico", ctx.query)}>Comparação técnica →</a>
          <button type="button" class="btnG" onClick={() => outlet.querySelectorAll<HTMLElement>(".l3").forEach(c => setLevel(c, 2))}>Abrir tudo em Prova</button></div>
      </div>
      <div class="stack"><div class="cards2">
        {metricCards}
        <LayerCard title="Folga da bateria" badge="nd" globalBadge={G}
          answer={<><span class="big">N/D</span>Não calculada para locais reais.</>}
          why="A bateria depende de painel, carga e reserva. Esse modelo só existe no painel de bordo, com dados sintéticos (SIM), e não é aplicado aqui."
          proof={[["Status", "não calculado"], ["Por quê", "sem modelo de energia validado para séries reais"]]} />
      </div></div>
    </div>
  </>);
}
